<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { getCatalogExams } from '@/api/catalog'; import { ApiAbortError, ApiError } from '@/api/http'; import EmptyState from '@/components/EmptyState.vue'; import ErrorState from '@/components/ErrorState.vue'; import LoadingState from '@/components/LoadingState.vue'; import Pagination from '@/components/CatalogPagination.vue'; import type { CatalogExamResponse } from '@/types/catalog'; import type { PagedResponse } from '@/types/api'
const route=useRoute();const router=useRouter();const pageSize=20;const search=ref('');const result=ref<PagedResponse<CatalogExamResponse>|null>(null);const loading=ref(false);const error=ref('');let controller:AbortController|null=null;let requestId=0
function formatTime(seconds:number):string{if(seconds<60)return `${seconds} сек.`;const minutes=Math.floor(seconds/60);const rest=seconds%60;return rest?`${minutes} мин. ${rest} сек.`:`${minutes} мин.`}
const q=()=>typeof route.query.search==='string'?route.query.search:'';const page=()=>{const n=Number(route.query.page);return Number.isInteger(n)&&n>0?n:1};const msg=(e:unknown)=>e instanceof ApiError?e.message:'Не удалось загрузить экзамены.'
async function load(){controller?.abort();controller=new AbortController();const id=++requestId;loading.value=true;error.value='';try{const p=page();result.value=await getCatalogExams({search:q(),page:p,pageSize,signal:controller.signal});const max=Math.max(1,Math.ceil(result.value.totalCount/pageSize));if(p>max)void router.replace({query:{...route.query,page:String(max)}})}catch(e){if(e instanceof ApiAbortError||id!==requestId)return;error.value=msg(e);result.value=null}finally{if(id===requestId)loading.value=false}}
function apply(){const s=search.value.trim().slice(0,200);void router.replace({name:'cashier-exams',query:s?{search:s}: {}})};function changePage(p:number){if(result.value&&p>=1&&p<=Math.ceil(result.value.totalCount/pageSize))void router.replace({query:{...route.query,page:String(p)}})};watch(()=>route.query,()=>{search.value=q();void load()},{immediate:true});onBeforeUnmount(()=>controller?.abort())
</script>
<template><section class="space-y-6"><div><p class="text-sm font-semibold uppercase tracking-wider text-brand">Проверка знаний</p><h1 class="mt-2 text-3xl font-bold text-ink">Экзамены</h1><p class="mt-2 text-muted">Подготовленные экзамены с правилами прохождения.</p></div><form class="flex flex-col gap-3 sm:flex-row" @submit.prevent="apply"><label class="sr-only" for="exam-search">Поиск экзаменов</label><input id="exam-search" v-model="search" class="app-input" maxlength="200" placeholder="Поиск экзаменов"/><button class="rounded-app bg-brand px-4 py-2.5 text-sm font-semibold text-white hover:bg-brand-hover" type="submit">Найти</button><button v-if="search" class="rounded-app border border-line bg-surface px-4 py-2.5 text-sm font-semibold text-ink hover:bg-canvas" type="button" @click="search='';apply()">Сбросить</button></form><LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" :retry="load"/><EmptyState v-else-if="!result||result.items.length===0" message="Экзамены по заданным условиям не найдены."/><div v-else class="space-y-3"><RouterLink v-for="exam in result.items" :key="exam.id" class="block rounded-app border border-line bg-surface p-5 shadow-sm transition hover:border-brand" :to="{name:'cashier-exam-detail',params:{id:exam.id},query:route.query}"><h2 class="text-lg font-semibold text-ink">{{ exam.title }}</h2><p v-if="exam.description" class="mt-2 text-sm text-muted">{{ exam.description }}</p><div class="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-sm text-muted"><span>Вопросов: {{ exam.questionCount }}</span><span>Время: {{ formatTime(exam.timeLimitSeconds) }}</span><span>Допустимо ошибок: {{ exam.maxWrongAnswers }}</span></div></RouterLink><Pagination :page="result.page" :page-size="result.pageSize" :total-count="result.totalCount" @change="changePage"/></div></section></template>
